extends Control

signal back_pressed

func _ready() -> void:
	# Disconnect scene connections to rewire as non-deferred
	var slider: HSlider = $VBoxContainer/VolumeSlider
	var option: OptionButton = $VBoxContainer/ResolutionOption
	var checkbox: CheckBox = $VBoxContainer/FullscreenCheck

	# Connect signals non-deferred (override scene-file connections)
	if not slider.value_changed.is_connected(_on_volume_changed):
		slider.value_changed.connect(_on_volume_changed)
	if not option.item_selected.is_connected(_on_resolution_selected):
		option.item_selected.connect(_on_resolution_selected)
	if not checkbox.toggled.is_connected(_on_fullscreen_toggled):
		checkbox.toggled.connect(_on_fullscreen_toggled)

	# Read existing values from GameSettings using set_value_no_signal to avoid
	# triggering value_changed (which would overwrite GameSettings with stale data)
	slider.set_value_no_signal(GameSettings.volume)
	option.selected = GameSettings.resolution_index
	checkbox.set_pressed_no_signal(GameSettings.fullscreen)

func _process(_delta: float) -> void:
	if Input.is_action_just_pressed("ui_back"):
		_on_back_pressed()

func _on_volume_changed(value: float) -> void:
	GameSettings.set_volume(value)

func _on_resolution_selected(index: int) -> void:
	GameSettings.set_resolution_index(index)

func _on_fullscreen_toggled(toggled_on: bool) -> void:
	GameSettings.set_fullscreen(toggled_on)

func _on_back_pressed() -> void:
	emit_signal("back_pressed")
