	assert(nb_p_top == buttons[2], "T3 FAILED: Play.top != Quit (wrap)")
	assert(nb_s_top == buttons[0], "T3 FAILED: Settings.top != Play")
	assert(nb_q_top == buttons[1], "T3 FAILED: Quit.top != Settings")
	print("T3 PASSED")

	print("--- T4: SettingsMenu scene structure ---")
	var sm_scene = load("res://scenes/SettingsMenu.tscn")
	assert(sm_scene != null, "T4 FAILED: can't load SettingsMenu.tscn")
	var sm_check = sm_scene.instantiate()
	get_root().add_child(sm_check)
	var slider_check = _find_type(sm_check, "HSlider")
	var option_check = _find_type(sm_check, "OptionButton")
	var check_check = _find_type(sm_check, "CheckBox")
	var back_check = _find_back_btn(sm_check)
	assert(slider_check != null, "T4 FAILED: no HSlider")
	assert(option_check != null, "T4 FAILED: no OptionButton")
	assert(option_check.item_count == 3, "T4 FAILED: OptionButton items=" + str(option_check.item_count))
	assert(check_check != null, "T4 FAILED: no CheckBox")
	assert(back_check != null, "T4 FAILED: no Back button")
	print("T4 PASSED")

	# Load RootUI for further tests
	var ru_scene = load("res://scenes/RootUI.tscn")
	assert(ru_scene != null, "RootUI.tscn load failed")
	ru = ru_scene.instantiate()
	get_root().add_child(ru)

func _process(_delta: float) -> bool:
	step += 1

	if step == 1:
		# After frame 1: _ready has run
		var mm = ru.get_node("MainMenu")
		var sm = ru.get_node("SettingsMenu")

		print("--- T5: RootUI _ready visibility ---")
		assert(mm.visible == true, "T5 FAILED: MainMenu should be visible")
		assert(sm.visible == false, "T5 FAILED: SettingsMenu should be hidden")
		print("T5 PASSED")

		print("--- T6: ui_back navigation ---")
		sm.visible = true
		mm.visible = false
		Input.action_press("ui_back")
		return false

	elif step == 2:
		Input.action_release("ui_back")
		var mm = ru.get_node("MainMenu")
		var sm = ru.get_node("SettingsMenu")
		assert(sm.visible == false, "T6 FAILED: SettingsMenu should be hidden after ui_back")
		assert(mm.visible == true, "T6 FAILED: MainMenu should be visible after ui_back")
		print("T6 PASSED")

		print("--- T7: HSlider -> GameSettings.volume + settings_changed ---")
		gs.volume = 1.0  # reset
		gs.settings_changed.connect(func(): signal_count += 1)
		var sm2 = ru.get_node("SettingsMenu")
		var slider = _find_type(sm2, "HSlider")
		assert(slider != null, "T7 FAILED: no HSlider in RootUI's SettingsMenu")
		slider.value = 0.42
		assert(gs.volume == 0.42, "T7 FAILED: gs.volume=" + str(gs.volume) + " expected 0.42")
		assert(signal_count >= 1, "T7 FAILED: settings_changed not emitted, count=" + str(signal_count))
		print("T7 PASSED: volume=", gs.volume, " signal_count=", signal_count)

		print("--- T8: SettingsMenu _ready reads GameSettings ---")
		gs.volume = 0.7
		gs.resolution_index = 2
		gs.fullscreen = true
		var sm3_scene = load("res://scenes/SettingsMenu.tscn")
		var sm3 = sm3_scene.instantiate()
		get_root().add_child(sm3)
		# Need another frame for _ready
		return false

	elif step == 3:
		# Check last sm3 added  
		# Find it - it's the last SettingsMenu added
		var sm3: Node = null
		for c in get_root().get_children():
			if c.name == "SettingsMenu" or (c.get_script() and str(c.get_script().resource_path).find("SettingsMenu") >= 0):
				sm3 = c
		# Actually let's track it differently
		# Find all nodes with VBoxContainer/VolumeSlider
		for c in get_root().get_children():
			if c.get_node_or_null("VBoxContainer/VolumeSlider") != null:
				var sl = c.get_node("VBoxContainer/VolumeSlider")
				if sl.value == 0.7:  # set via set_value_no_signal in _ready
					sm3 = c
					break
		if sm3 == null:
			# fallback: find by script
			for c in get_root().get_children():
				if c.get_node_or_null("VBoxContainer") != null:
					var ch = c.get_node("VBoxContainer").get_children()
					if ch.size() > 0 and ch[0] is HSlider:
						var sl: HSlider = ch[0]
						if sl.value == 0.7:
							sm3 = c
							break
		assert(sm3 != null, "T8 FAILED: could not find new SettingsMenu instance")
		var sl3: HSlider = _find_type(sm3, "HSlider")
		var op3: OptionButton = _find_type(sm3, "OptionButton")
		var cb3: CheckBox = _find_type(sm3, "CheckBox")
		assert(sl3.value == 0.7, "T8 FAILED: slider.value=" + str(sl3.value) + " expected 0.7")
		assert(op3.selected == 2, "T8 FAILED: option.selected=" + str(op3.selected) + " expected 2")
		assert(cb3.button_pressed == true, "T8 FAILED: checkbox should be true")
		print("T8 PASSED")

		print("=== ALL TESTS PASSED ===")
		quit(0)

	return false

func _find_type(parent: Node, type_name: String) -> Node:
	if parent.get_class() == type_name:
		return parent
	for c in parent.get_children():
		var r = _find_type(c, type_name)
		if r: return r
	return null

func _find_back_btn(parent: Node) -> Button:
	if parent is Button and parent.text == "Back":
		return parent
	for c in parent.get_children():
		var r = _find_back_btn(c)
		if r: return r
	return null
